Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",

  "data": {
    "name": "dataset"
  },

  "width": "container",
  "height": "container",

  "transform": [
    {
      "aggregate": [
        {
          "op": "sum",
          "field": "FLORES",
          "as": "TotalFlores"
        }
      ],
      "groupby": [
        "Nombre corto"
      ]
    },
    {
      "window": [
        {
          "op": "rank",
          "as": "Ranking"
        }
      ],
      "sort": [
        {
          "field": "TotalFlores",
          "order": "descending"
        }
      ]
    },
    {
      "calculate": "datum.Ranking <= 3 ? ''#D4AF37'' : ''#3B82F6''",
      "as": "ColorBarra"
    }
  ],

  "layer": [

    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 8,
        "height": 20
      },

      "encoding": {

        "y": {
          "field": "Nombre corto",
          "type": "nominal",
          "sort": "-x",
          "title": null,
          "axis": {
            "labelFontSize": 12,
            "labelLimit": 180
          }
        },

        "x": {
          "field": "TotalFlores",
          "type": "quantitative",
          "title": null,
          "axis": {
            "format": ",.2f",
            "grid": false,
            "labelFontSize": 11
          }
        },

    "color": {
  "field": "TotalFlores",
  "type": "quantitative",
  "legend": null,
  "scale": {
    "domain": [
      0,
      50000,
      90000,
      120000,
      170000
    ],
    "range": [
      "#D73027",
      "#F8B15C",
      "#F7E58A",
      "#8BCF63",
      "#0B7A3E"
    ]
  }

        },

        "tooltip": [
          {
            "field": "Ranking",
            "title": "Ranking"
          },
          {
            "field": "Nombre corto",
            "title": "Evaluador"
          },
          {
            "field": "TotalFlores",
            "title": "Flores",
            "format": ",.2f"
          }
        ]
      }
    },

    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 6,
        "fontSize": 12,
        "fontWeight": "bold",
        "color": "#333"
      },

      "encoding": {

        "y": {
          "field": "Nombre corto",
          "type": "nominal",
          "sort": "-x"
        },

        "x": {
          "field": "TotalFlores",
          "type": "quantitative"
        },

        "text": {
          "field": "TotalFlores",
          "type": "quantitative",
          "format": ",.2f"
        }
      }
    }

  ],

  "config": {

    "view": {
      "stroke": null
    },

    "axis": {
      "domain": false,
      "tickSize": 0
    }

  }
}'
